-- Fakt kartochkalari orqa tomonining ruscha matni — 67-partiya:
-- Ibroyim Yusupov, Imom at-Termiziy, Komil Xorazmiy.

UPDATE fact_cards SET detail_ru = 'Ибрайим Юсупов родился 5 мая 1929 года в селении Озод Чимбайского района Каракалпакстана. Позже он стал одним из виднейших представителей каракалпакской поэзии. Источник: Ziyouz.com, страница «Ибрайим Юсупов (1929–2008)».' WHERE id = 2194;
UPDATE fact_cards SET detail_ru = 'В 1949 году он окончил Каракалпакский государственный педагогический институт. После этого он до 1961 года преподавал студентам в том же институте. Источник: Ziyouz.com, страница «Ибрайим Юсупов (1929–2008)».' WHERE id = 2195;
UPDATE fact_cards SET detail_ru = 'Первое стихотворение поэта «Моя родина» было напечатано в 1946 году. Пробовал он перо и в прозе: в 1963 году издал сборник рассказов «Осень старого тута». Источник: Ziyouz.com, страница «Ибрайим Юсупов (1929–2008)».' WHERE id = 2196;
UPDATE fact_cards SET detail_ru = 'Были изданы такие стихотворные сборники поэта, как «Лирика счастья» (1955), «Путнику на восход» (1959), «Раздумья» (1960), «Семь напевов» (1962), «Мечты поля» (1966), «Сердце пьёт из сердца» (1971), «Томирис» (1974), «Мир, полный забот» (1987), «Солёные ветры» (1988), «У каждого своё время» (2004). Его лирика считается одной из ярких страниц каракалпакской поэзии. Источник: Ziyouz.com, страница «Ибрайим Юсупов (1929–2008)».' WHERE id = 2197;
UPDATE fact_cards SET detail_ru = 'Вместе с Аметом Шамуратовым он создал пьесу «Сорок девушек». В 1966 году он написал комедию «Балагур Умирбек», в 1986-м — драму «Сон царя Искандера», а в 1973 году сложил либретто оперы «Аджинияз». Источник: Ziyouz.com, страница «Ибрайим Юсупов (1929–2008)».' WHERE id = 2198;
UPDATE fact_cards SET detail_ru = 'Ибрайим Юсупов переложил на каракалпакский язык сочинения Пушкина, Лермонтова, Шевченко, Байрона, Гёте, Гейне, Шиллера и Шекспира. Он также перевёл стихи Алишера Навои и Омара Хайяма и тем обогатил национальную словесность. Источник: Ziyouz.com, страница «Ибрайим Юсупов (1929–2008)».' WHERE id = 2199;
UPDATE fact_cards SET detail_ru = 'В 1961–1962 годах он был главным редактором журнала «Амударья», затем работал научным сотрудником в Институте языка и литературы. В 1965–1980 годах он был председателем Союза писателей Каракалпакстана, в 1980–1988 годах — главным редактором газеты «Эркин Каракалпакстан». В 1988–1994 годах он возглавлял каракалпакское отделение Комитета мира, а в 1994–2000 годах — Республиканский центр духовности и просвещения. Источник: Ziyouz.com, страница «Ибрайим Юсупов (1929–2008)».' WHERE id = 2200;
UPDATE fact_cards SET detail_ru = 'В 1975 году Ибрайиму Юсупову было присвоено звание народного поэта Узбекистана и Каракалпакстана. В 1974 году он был удостоен Государственной премии Каракалпакстана имени Бердаха, а в 2004 году указом Президента — звания «Герой Узбекистана». Награждён он и орденами «Эл-юрт хурмати» и «Дустлик». Источник: Ziyouz.com, страница «Ибрайим Юсупов (1929–2008)».' WHERE id = 2201;
UPDATE fact_cards SET detail_ru = 'Ибрайим Юсупов умер в 2008 году. Его стихи заняли место в золотой сокровищнице каракалпакской словесности. Источник: Ziyouz.com, страница «Ибрайим Юсупов (1929–2008)».' WHERE id = 2202;

UPDATE fact_cards SET detail_ru = 'Селение Буг находится на территории нынешнего Шерабадского района Сурхандарьинской области. Дед учёного был родом из Мерва и позже переселился в Термез; поскольку вся его жизнь была теснейшим образом связана с Термезом, в народе он и стал известен под именем ат-Термези. Источник: Ziyouz.com, статья «Абу Иса ат-Термези» (У. Уватов, «Два великих мудреца», Ташкент, 2005).' WHERE id = 1867;
UPDATE fact_cards SET detail_ru = 'Эти сведения отметил известный среднеазиатский историк Абу Саад Абдулкарим ас-Самани (1113–1167): поскольку учёный умер в селении Буг, его называли и под прозванием аль-Буги. Некоторые авторы говорят, что учёный был слеп от рождения, но большинство пишет, что он ослеп позже, на исходе жизни. Источник: Ziyouz.com, статья «Абу Иса ат-Термези».' WHERE id = 1868;
UPDATE fact_cards SET detail_ru = 'Как отмечает историк Шамсуддин аз-Захаби, ат-Термези сам не посещал Египта и Шама, потому хадисы от учёных этих стран он передавал через посредников. В своих странствиях, кроме науки о хадисах, он брал уроки и по чтению Корана, по риторике, праву и истории. Источник: Ziyouz.com, статья «Абу Иса ат-Термези».' WHERE id = 1869;
UPDATE fact_cards SET detail_ru = 'Его наставник имам аль-Бухари высоко оценил его знания, сказав ему: «Пользы, полученной мною от тебя, больше, чем пользы, полученной тобою от меня». Между двумя учёными в 863–868 годах в Нишапуре проходили многочисленные плодотворные научные прения. Источник: Ziyouz.com, статья «Абу Иса ат-Термези».' WHERE id = 1870;
UPDATE fact_cards SET detail_ru = 'Этот рассказ привёл арабский историк Шамсуддин аз-Захаби (1274–1347) в сочинении «Тазкират уль-хуффаз». По другому преданию, когда шейх произнёс сорок из своих редких хадисов, ат-Термези повторил их все от начала до конца один за другим, и шейх сказал: «Подобного тебе я никогда не видел». Источник: Ziyouz.com, статья «Абу Иса ат-Термези».' WHERE id = 1871;
UPDATE fact_cards SET detail_ru = 'Учёный Такиуддин ибн Таймия свидетельствовал: «Абу Иса ат-Термези — учёный, первым разделивший хадисы на достоверные, хорошие и слабые». И хафиз ибн Раджаб в своих книгах отмечал его как одного из первых, кто разделил хадисы на достоверные, хорошие и редкие. Источник: Ziyouz.com, статья «Абу Иса ат-Термези».' WHERE id = 1872;
UPDATE fact_cards SET detail_ru = 'Это сочинение известно и под названиями «Аль-Джами аль-кабир», «Сахих ат-Термези», «Сунан ат-Термези» и считается одной из шести самых надёжных книг — «кутуб ситта». Сам автор написал: «В чьём доме есть эта книга, в том доме будто говорит сам пророк, мир ему». Источник: Ziyouz.com, статья «Абу Иса ат-Термези».' WHERE id = 1873;
UPDATE fact_cards SET detail_ru = 'Известны и такие сочинения учёного, как «Рисала фи-ль-хиляф ва-ль-джадаль» и «Асма ус-сахаба». Рукописи «Аль-Джами ас-сахих» хранятся и в Институте востоковедения имени Абу Райхана Беруни Академии наук Узбекистана. Источник: Ziyouz.com, статья «Абу Иса ат-Термези».' WHERE id = 1874;
UPDATE fact_cards SET detail_ru = 'Сочинение излагает внешний облик и нравственные достоинства пророка, мир ему, и переведено также на персидский и турецкий языки. На узбекский его переложил наш соотечественник Саид Махмуд Тарази. Источник: Ziyouz.com, статья «Абу Иса ат-Термези».' WHERE id = 1875;
UPDATE fact_cards SET detail_ru = 'Сочинения учёного ценились и после его смерти: «Аль-Джами ас-сахих» был издан в 1283 году хиджры (1866) в Митохе, в 1292 году хиджры (1875) в Каире, в 1980 году в Бейруте, и к нему написаны десятки толкований. Источник: Ziyouz.com, статья «Абу Иса ат-Термези».' WHERE id = 1876;

UPDATE fact_cards SET detail_ru = 'Комил Хорезми родился в 1825 году в Хиве. Настоящее его имя — Палван Мухаммадниёз, сын Абдуллы Ахунда, а «Комил» — литературный псевдоним. Источник: Ziyouz.com.' WHERE id = 1999;
UPDATE fact_cards SET detail_ru = 'Комил Хорезми учился в хивинском медресе. Он в совершенстве владел арабским и персидским языками. Источник: Ziyouz.com.' WHERE id = 2000;
UPDATE fact_cards SET detail_ru = 'Он был писцом при дворе Сайида Мухаммад-хана, а затем Мухаммад Рахим II назначил его мирзабаши. В 1873–1880 годах он был диванбеги, а с 1880 года снова служил в должности мирзабаши. Источник: Ziyouz.com.' WHERE id = 2001;
UPDATE fact_cards SET detail_ru = 'Гандимиянский мирный договор между Россией и Хивинским ханством был в 1873 году написан рукою Комила Хорезми. Это было связано с его придворной должностью мирзабаши. Источник: Ziyouz.com.' WHERE id = 2002;
UPDATE fact_cards SET detail_ru = 'Комил Хорезми ввёл нотную систему «танбурная черта» и записал этой нотацией главную часть макома «Раст». Запись остальных частей хорезмского «Шашмакома» продолжил его сын Мирза Мухаммадрасул. Источник: Ziyouz.com.' WHERE id = 2003;
UPDATE fact_cards SET detail_ru = 'В диване Комила Хорезми собрано более восьми тысяч строк стихов в жанрах газели, рубаи, касыды и других. В них возвеличиваются человеческие достоинства и обличается невежество. Источник: Ziyouz.com.' WHERE id = 2004;
UPDATE fact_cards SET detail_ru = 'В 1865 году он переложил с персидского на узбекский сочинение «Махбуб уль-кулуб», а в 1869–1870 годах — «Латоиф ат-тавоиф». В 1880–1881 годах он первым в Хорезме устроил типографию и написал предисловие к первому хорезмскому литографскому изданию «Хамсы» Навои. Источник: Ziyouz.com.' WHERE id = 2005;
UPDATE fact_cards SET detail_ru = 'Комил Хорезми умер в 1899 году. Его рукописи хранятся в фонде Института востоковедения Академии наук Узбекистана. Источник: Ziyouz.com.' WHERE id = 2006;
